python3 - <<'PY'
from pathlib import Path
from collections import defaultdict
from datetime import date, datetime, timedelta
import re

log_dir = Path('/app/logs')
reference_date = date(2025, 8, 12)
severities = ['ERROR', 'WARNING', 'INFO']
counts = defaultdict(lambda: {s: 0 for s in severities})
file_pattern = re.compile(r'^(\d{4}-\d{2}-\d{2})_[^/]+\.log$')
severity_pattern = re.compile(r'\[([^]]+)\]')

for path in sorted(log_dir.glob('*.log')):
    match = file_pattern.match(path.name)
    if not match:
        continue
    event_date = datetime.strptime(match.group(1), '%Y-%m-%d').date()
    with path.open(encoding='utf-8', errors='replace') as fh:
        for line in fh:
            severity_match = severity_pattern.search(line)
            if not severity_match:
                continue
            severity = severity_match.group(1).strip()
            if severity in severities:
                counts[event_date][severity] += 1

total = {s: sum(counts[d][s] for d in counts) for s in severities}

def window_count(period, severity):
    if period == 'total':
        return total[severity]
    if period == 'today':
        start = end = reference_date
    elif period == 'last_7_days':
        start = reference_date - timedelta(days=6)
        end = reference_date
    elif period == 'last_30_days':
        start = reference_date - timedelta(days=29)
        end = reference_date
    elif period == 'month_to_date':
        start = date(2025, 8, 1)
        end = reference_date
    else:
        raise ValueError(period)
    return sum(counts[d][severity] for d in counts if start <= d <= end)

lines = ['period,severity,count']
for period in ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']:
    for severity in severities:
        lines.append(f'{period},{severity},{window_count(period, severity)}')

Path('/app/summary.csv').write_text('\n'.join(lines) + '\n')
